import{_ as s,o as t,c as r,aN as e}from"./chunks/framework.D31DlcCL.js";const n="/img/math-perimeter-clever.svg",d=JSON.parse('{"title":"几何进阶：巧求周长，学会图形的“瞬移术”","description":"面对凹凸不平的不规则图形，除了把每一条边加起来，还有更快的办法吗？本文教你掌握求周长的“平移大法”，让复杂的图形瞬间变回简单的小长方形。","frontmatter":{"title":"几何进阶：巧求周长，学会图形的“瞬移术”","date":"2026-02-19T11:00:00.000Z","categories":["数学"],"tags":["小学数学","几何计算","周长问题","平移法"],"description":"面对凹凸不平的不规则图形，除了把每一条边加起来，还有更快的办法吗？本文教你掌握求周长的“平移大法”，让复杂的图形瞬间变回简单的小长方形。","cover":"/img/math-perimeter-clever.svg","top_img":"/img/math-perimeter-clever.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-perimeter-clever.md","filePath":"posts/primary-math-perimeter-clever.md","lastUpdated":null}'),o={name:"posts/primary-math-perimeter-clever.md"};function l(m,a,i,p,h,c){return t(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="几何进阶-巧求周长-学会图形的-瞬移术" tabindex="-1">几何进阶：巧求周长，学会图形的“瞬移术” <a class="header-anchor" href="#几何进阶-巧求周长-学会图形的-瞬移术" aria-label="Permalink to &quot;几何进阶：巧求周长，学会图形的“瞬移术”&quot;">​</a></h1><p>在计算图形的周长时，我们最熟悉的公式是：</p><ul><li>正方形周长 = 边长 × 4</li><li>长方形周长 = (长 + 宽) × 2</li></ul><p>但如果遇到一个像台阶一样的“凹”图形，或者一个缺了一角的形状，公式似乎就不灵了。其实，只要学会了**“平移法”**，这些不规则图形在你眼里都会变成整齐的长方形。</p><hr><h2 id="一、-核心法宝-平移大法" tabindex="-1">一、 核心法宝：平移大法 <a class="header-anchor" href="#一、-核心法宝-平移大法" aria-label="Permalink to &quot;一、 核心法宝：平移大法&quot;">​</a></h2><p>平移法的精髓是：<strong>把那些“缩”在里面的线条，推到外面去。</strong></p><p><img src="'+n+'" alt="平移求周长示意图"></p><p><strong>【操作流程】</strong>：</p><ol><li><strong>观察</strong>：找出图形中水平和垂直的线条。</li><li><strong>平移</strong>：把凹进去的水平线往上（或往下）推，把凹进去的垂直线往左（或往右）推。</li><li><strong>补全</strong>：你会惊讶地发现，这些线条正好拼成了一个完整长方形的边！</li></ol><hr><h2 id="二、-实战模型解析" tabindex="-1">二、 实战模型解析 <a class="header-anchor" href="#二、-实战模型解析" aria-label="Permalink to &quot;二、 实战模型解析&quot;">​</a></h2><h3 id="模型-1-楼梯型图形" tabindex="-1">模型 1：楼梯型图形 <a class="header-anchor" href="#模型-1-楼梯型图形" aria-label="Permalink to &quot;模型 1：楼梯型图形&quot;">​</a></h3><p><strong>【例题 1】</strong>：一个像楼梯一样的图形，长 10 厘米，高 8 厘米。求它的周长。 <strong>解析</strong>： 虽然楼梯有很多小折线，但所有的“横线”加起来正好等于最下面的大长（10厘米），所有的“竖线”加起来正好等于最左边的大宽（8厘米）。 <strong>计算</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>1</mn><mn>0</mn><mo>+</mo><mn>8</mn><mo>)</mo><mo>×</mo><mn>2</mn><mo>=</mo><mn>3</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">(10 + 8) \\times 2 = 36</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">8</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span></span></span></span>（厘米）。 <strong>答案</strong>：36 厘米。</p><h3 id="模型-2-凹字型图形-要小心" tabindex="-1">模型 2：凹字型图形（要小心！） <a class="header-anchor" href="#模型-2-凹字型图形-要小心" aria-label="Permalink to &quot;模型 2：凹字型图形（要小心！）&quot;">​</a></h3><p><strong>【例题 2】</strong>：一个长方形中间挖掉了一个小缺口（凹字型）。 <strong>解析</strong>： 平移后，你会发现左右两边的线可以补全，但<strong>底部的线条无法平移抵消</strong>。 <strong>结论</strong>：凹字型周长 = 大长方形周长 + 缺口的两条侧边长 × 2。</p><hr><h2 id="三、-进阶技巧-化曲为直" tabindex="-1">三、 进阶技巧：化曲为直 <a class="header-anchor" href="#三、-进阶技巧-化曲为直" aria-label="Permalink to &quot;三、 进阶技巧：化曲为直&quot;">​</a></h2><p>虽然我们现在主要研究直线图形，但平移的思想也可以扩展。</p><ul><li><strong>关键点</strong>：只要线条的长度没有因为平移而改变，周长就守恒。</li></ul><hr><h2 id="四、-避坑指南-不要漏算-隐藏边" tabindex="-1">四、 避坑指南：不要漏算“隐藏边” <a class="header-anchor" href="#四、-避坑指南-不要漏算-隐藏边" aria-label="Permalink to &quot;四、 避坑指南：不要漏算“隐藏边”&quot;">​</a></h2><ul><li><strong>陷阱</strong>：在平移时，一定要看清楚哪些边是补全了外框，哪些边是多出来的。</li><li><strong>提醒</strong>：只有向外推能拼成直线的边才适用平移简化，那些多出来的“深坑”侧壁一定要单独加回来。</li></ul><hr><h2 id="五、-练一练-几何小侦探" tabindex="-1">五、 练一练（几何小侦探） <a class="header-anchor" href="#五、-练一练-几何小侦探" aria-label="Permalink to &quot;五、 练一练（几何小侦探）&quot;">​</a></h2><ol><li><strong>基础关</strong>：一个 L 形图形，水平方向最长 6 厘米，垂直方向最长 5 厘米。求周长。</li><li><strong>进阶关</strong>：一个长 12 厘米、宽 10 厘米的长方形，在四个角各剪掉一个边长 2 厘米的小正方形。剩下的图形周长是多少？</li><li><strong>挑战关</strong>：一个“凸”字形图形，底长 10，总高 8，上部凸起部分宽 4。它的周长和原来的 10×8 长方形比，变了吗？</li></ol><hr><p><em>总结：巧求周长的核心是“空间补全”。只要你学会了平移线条，再破碎的图形也能被你整理成最完美的几何体！</em></p>',28)])])}const u=s(o,[["render",l]]);export{d as __pageData,u as default};
